package com.payshield.repo; import com.payshield.domain.IdempotencyRecord; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface IdempotencyRepository extends JpaRepository<IdempotencyRecord,UUID>{ @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select r from IdempotencyRecord r where r.idempotencyKey=:key") Optional<IdempotencyRecord> lockByKey(@Param("key") String key); }
